import { ROLE_LABELS, type PlatformRole, type UserSession } from '@pacom/contracts';
import { DemoAdapter } from '../adapters/demo-adapter';
import { mountAppShell } from '../app/shell';
import { renderIcon } from '../design-system/icons';
import { mountLoginView } from '../features/auth/login-view';
import './demo-bar.css';

const DEMO_ROLES: PlatformRole[] = ['org_admin', 'project_admin', 'operator', 'space_user'];

/**
 * 独立演示工作台入口（仅在 demo.html 加载，与真实业务页面代码物理隔离）
 * 真实业务壳层直接铺满 100% 视口（与 index.html 像素级一致），角色切换仅以右下角可折叠浅色悬浮胶囊呈现。
 */
export async function mountDemoWorkbench(host: HTMLElement): Promise<void> {
  const adapter = new DemoAdapter();
  let session: UserSession | null = await adapter.getSession();
  let fabOpen = false;

  document.querySelector('[data-demo-fab-root]')?.remove();
  const fabRoot = document.createElement('div');
  fabRoot.className = 'pacom-demo-fab-wrap';
  fabRoot.dataset.demoFabRoot = '1';
  document.body.appendChild(fabRoot);

  function renderDemoFab(): void {
    const activeRoleLabel = session ? ROLE_LABELS[session.role] : '未登录';
    fabRoot.innerHTML = `
      ${
        fabOpen
          ? `
          <div class="pacom-demo-fab-panel" role="dialog" aria-label="演示视角切换">
            <div class="pacom-demo-fab-head">
              <span class="pacom-demo-fab-title">独立演示视角</span>
              <span class="pacom-badge pacom-badge--neutral">模拟数据</span>
            </div>
            <span class="pacom-demo-fab-sub">点击切换 4 级标准角色体验权限裁剪与限时提权</span>
            <div class="pacom-demo-fab-roles">
              ${DEMO_ROLES.map(
                (r) => `
                  <button type="button" class="pacom-demo-role-btn" aria-pressed="${session?.role === r}" data-demo-pick="${r}">
                    <span>${ROLE_LABELS[r]}</span>
                    ${session?.role === r ? renderIcon('check', 14) : ''}
                  </button>`
              ).join('')}
            </div>
            <div class="pacom-demo-fab-foot">
              <a class="pacom-demo-link" href="./index.html">
                <span>前往真实联调入口（index.html）</span>
                <span>→</span>
              </a>
            </div>
          </div>`
          : ''
      }
      <button type="button" class="pacom-demo-fab-pill" aria-expanded="${fabOpen}" data-demo-fab-toggle="1" title="切换演示角色">
        <span class="pacom-demo-fab-dot" aria-hidden="true"></span>
        <span>演示</span>
        <span class="pacom-demo-fab-role">${activeRoleLabel}</span>
        ${renderIcon(fabOpen ? 'chevron-down' : 'chevrons-up-down', 12)}
      </button>
    `;

    fabRoot.querySelector<HTMLButtonElement>('[data-demo-fab-toggle]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      fabOpen = !fabOpen;
      renderDemoFab();
    });

    fabRoot.querySelectorAll<HTMLButtonElement>('[data-demo-pick]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const nextRole = btn.dataset.demoPick as PlatformRole | undefined;
        if (!nextRole) return;
        fabOpen = false;
        session = await adapter.switchDemoRole(nextRole);
        await enterApp(session);
      });
    });
  }

  document.addEventListener('click', (e) => {
    if (!fabOpen) return;
    if (!(e.target as HTMLElement | null)?.closest('[data-demo-fab-root]')) {
      fabOpen = false;
      renderDemoFab();
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && fabOpen) {
      fabOpen = false;
      renderDemoFab();
    }
  });

  async function enterApp(activeSession: UserSession): Promise<void> {
    session = activeSession;
    renderDemoFab();
    if (!window.location.hash || window.location.hash === '#login') {
      window.location.hash = '#home';
    }
    await mountAppShell(host, adapter, activeSession, () => {
      session = null;
      renderDemoFab();
      mountLoginView(host, adapter, (nextSession) => {
        void enterApp(nextSession);
      });
    });
  }

  renderDemoFab();

  if (!session || window.location.hash === '#login') {
    if (!session) {
      session = await adapter.switchDemoRole('org_admin');
      await enterApp(session);
      return;
    }
    mountLoginView(host, adapter, (nextSession) => {
      void enterApp(nextSession);
    });
    return;
  }

  await enterApp(session);
}
