import './design-system/tokens.css';
import './design-system/app-shell.css';
import './design-system/nav-shell.css';
import './features/auth/auth-407.css';
import { mountDemoWorkbench } from './demo/demo-workbench';

async function bootstrapDemo(): Promise<void> {
  const root = document.getElementById('app');
  if (!root) return;
  try {
    await mountDemoWorkbench(root);
  } catch (err) {
    root.innerHTML = `<div class="pacom-shell"><div class="pacom-alert-banner">演示环境初始化失败：${String(err)}</div></div>`;
  }
}

void bootstrapDemo();
