function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function parseFloorOrder(name: string): number {
  const upper = name.trim().toUpperCase();
  if (upper === 'RF' || upper === 'R' || upper === 'ROOF' || upper.includes('屋面') || upper.includes('屋顶') || upper.includes('天面')) return 999;
  const m = upper.match(/(-?\d+)/);
  if (!m) return 0;
  const n = Number(m[1]);
  return upper.startsWith('B') || upper.includes('地下') || upper.includes('负') ? -Math.abs(n) : n;
}

const CN_NUM_MAP: Record<string, number> = {
  一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9, 十: 10,
  十一: 11, 十二: 12, 十三: 13, 十四: 14, 十五: 15, 十六: 16, 十七: 17, 十八: 18, 十九: 19,
  二十: 20, 二十一: 21, 二十二: 22, 二十三: 23, 二十四: 24, 二十五: 25,
};

function normalizeFloorMatchKey(raw: string): string | null {
  const trimmed = raw.trim();
  const upper = trimmed.toUpperCase();
  if (/(?:^|[-_\s/])(RF|ROOF)(?:[-_.\s]|$)/.test(upper) || /屋面|屋顶|天面/.test(trimmed)) return 'RF';
  const bEn = upper.match(/(?:^|[-_\s/])B0*(\d+)(?:F)?(?:[-_.\s]|$)/);
  if (bEn) return `B${Number(bEn[1])}`;
  const bCn = trimmed.match(/(?:地下|负)(0*\d+|[一二三四五六七八九十]+)(?:层|楼)?/);
  if (bCn) {
    const n = /^\d+$/.test(bCn[1]!) ? Number(bCn[1]) : CN_NUM_MAP[bCn[1]!];
    if (n) return `B${n}`;
  }
  if (/首层|一层/.test(trimmed)) return '1F';
  const fCn = trimmed.match(/(0*\d+|[一二三四五六七八九十]+)(?:层|楼)/);
  if (fCn) {
    const n = /^\d+$/.test(fCn[1]!) ? Number(fCn[1]) : CN_NUM_MAP[fCn[1]!];
    if (n) return `${n}F`;
  }
  const fMatch = upper.match(/(?:^|[-_\s/])0*(\d+)F(?:[-_.\s]|$)/);
  if (fMatch) return `${Number(fMatch[1])}F`;
  return null;
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => (typeof reader.result === 'string' ? resolve(reader.result) : reject(new Error('无法读取图片内容')));
    reader.onerror = () => reject(new Error(`读取文件「${file.name}」失败`));
    reader.readAsDataURL(file);
  });
}

function shortDeployPinLabel(d: DeviceEntity): string {
  if (d.category === 'gateway') return d.name.includes('蓝牙') ? '蓝牙适配器' : '主控网关';
  if (d.category === 'lighting') return d.name.includes('702') ? '702 照明' : d.name.slice(0, 6);
  if (d.category === 'hvac') return d.name.includes('VAV') ? 'VAV-02' : d.name.includes('FCU') ? 'FCU-01' : d.name.slice(0, 6);
  if (d.category === 'sensor') return '环境传感';
  return d.name.slice(0, 6);
}

function buildSensorQualityRows(conn: SystemConnection, devices: DeviceEntity[]): SensorQualityRow[] {
  const degraded = conn.status !== 'connected';
  const matched = devices.filter((d) => d.hardwareBinding?.protocol === conn.protocol);
  if (matched.length > 0) {
    return matched.map((d) => {
      const isOff = d.connectivity === 'offline' || degraded;
      return {
        pointName:
          d.category === 'hvac'
            ? '送风温度 / 阀门开度'
            : d.category === 'lighting'
              ? '回路开关 / 亮度反馈'
              : d.category === 'sensor'
                ? '温湿度 / CO₂ / 人感'
                : '网关心跳 / 负载',
        deviceName: d.name,
        value: isOff
          ? '无上报'
          : d.category === 'hvac'
            ? '23.4°C · 62%'
            : d.category === 'lighting'
              ? '开启 · 80%'
              : d.category === 'sensor'
                ? '23.2°C · 640 ppm'
                : '负载 24% · 18ms',
        interval: '60s',
        lastSeen: isOff ? '46 分钟前' : '12 秒前',
        quality: isOff ? (d.connectivity === 'offline' ? 'offline' : 'delayed') : 'online',
      };
    });
  }
  return [
    {
      pointName: `${conn.protocol.toUpperCase()} 采集通道汇总点`,
      deviceName: conn.name,
      value: degraded ? '采样延迟' : '正常上报',
      interval: '60s',
      lastSeen: degraded ? '38 分钟前' : '9 秒前',
      quality: degraded ? 'delayed' : 'online',
    },
  ];
}

