  function runSingleDeviceFtt(dev: DeviceEntity): void {
    errorMsg = '';
    if (dev.connectivity === 'offline') {
      errorMsg = `单机回读自检未通过（FAIL）：「${dev.name}」当前离线，请核查网关链路或中继覆盖。`;
    } else {
      notice = `单机回读自检通过（PASS）：「${dev.name}」指令下发与状态回读一致，已安全复位。`;
    }
    render();
  }

  function runBatchFtt(): void {
    errorMsg = '';
    const curDevs = allDevicesForFloor(activeFloorId);
    const failedDevs = curDevs.filter((d) => d.connectivity === 'offline');
    const passed = curDevs.length - failedDevs.length;
    const now = new Date();
    const ranAt = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;
    batchFttResult = { ranAt, total: curDevs.length, passed, failed: failedDevs.length, failedNames: failedDevs.map((d) => d.name) };
    if (failedDevs.length > 0) {
      errorMsg = `全层批量自检完成：${passed}/${curDevs.length} 台通过，${failedDevs.length} 台异常（${failedDevs.map((d) => d.name).join('、')}）。`;
    } else {
      notice = `全层批量自检全部通过（${passed}/${curDevs.length}），设备已自动安全复位。`;
    }
    render();
  }

  function runMeshHealthCheck(): void {
    const curDevs = allDevicesForFloor(activeFloorId);
    const findings: MeshCheckFinding[] = [];
    const offline = curDevs.filter((d) => d.connectivity === 'offline');
    const unplaced = curDevs.filter((d) => !d.planPoint);
    const proxyCount = curDevs.filter((d) => meshRoles.get(d.id)?.proxy).length;
    const relayCount = curDevs.filter((d) => meshRoles.get(d.id)?.relay).length;
    const relayRatio = curDevs.length ? relayCount / curDevs.length : 0;

    if (offline.length > 0) {
      offline.forEach((d) =>
        findings.push({
          level: 'fail',
          title: `节点不可达：${d.name}`,
          detail: '建议检查供电、通信端子，若属无线节点可在遮挡拐角处增设中继节点。',
          deviceId: d.id,
        })
      );
    } else {
      findings.push({ level: 'ok', title: '全网节点可达性正常', detail: `${curDevs.length} 台设备均正常响应心跳。` });
    }
    if (proxyCount < 1) {
      findings.push({ level: 'warn', title: '缺少代理节点（Proxy）', detail: '建议每层至少开启 1–3 个传感器的 Proxy 功能，方便现场 App 接入网络。' });
    } else {
      findings.push({ level: 'ok', title: `代理节点配置合理（${proxyCount} 个）`, detail: '满足现场移动端多区域快速接入要求。' });
    }
    if (relayRatio > 0.25 && curDevs.length >= 4) {
      findings.push({ level: 'warn', title: `中继比例偏高（${Math.round(relayRatio * 100)}%）`, detail: '建议中继节点控制在总设备数 10% 左右，避免广播风暴。' });
    }
    if (unplaced.length > 0) {
      findings.push({ level: 'warn', title: `尚有 ${unplaced.length} 台未完成设备标记`, detail: '请在「设备管理 → 设备标记」中补齐平面坐标以便施工定位。' });
    }
    meshFindings = findings;
    notice = `已完成蓝牙 Mesh 网络体检（检测 ${curDevs.length} 台节点，发现 ${findings.filter((f) => f.level !== 'ok').length} 项关注）。`;
    render();
  }

  function exportDevicesCsv(): void {
    const curDevs = allDevicesForFloor(activeFloorId);
    const rows = [
      ['设备名称', '类别', '功能区', '图上坐标', '协议与地址', '物理复核', '在线状态'].join(','),
      ...curDevs.map((d) =>
        [
          d.name,
          d.category,
          getZoneLabel(d.logicalZoneId),
          d.planPoint ? `${Math.round(d.planPoint.x * 100)}%/${Math.round(d.planPoint.y * 100)}%` : '未标记',
          d.hardwareBinding ? `${d.hardwareBinding.protocol} ${d.hardwareBinding.networkAddress}` : '未绑定',
          d.physicalInstalled ? '已复核' : '待复核',
          d.connectivity === 'online' ? '在线' : '离线',
        ].join(',')
      ),
    ];
    const blob = new Blob([`\uFEFF${rows.join('\n')}`], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'pacom-device-list.csv';
    a.click();
    URL.revokeObjectURL(url);
  }

  function missingFloorSpecs(bld: SpatialTree['buildings'][number]): Array<{ kind: 'above' | 'below' | 'roof'; level: number; name: string }> {
    const existingKeys = new Set(
      sortedBuildingFloors(bld.id).map((f) => normalizeFloorMatchKey(f.name) ?? f.name.toUpperCase())
    );
    const missing: Array<{ kind: 'above' | 'below' | 'roof'; level: number; name: string }> = [];
    for (let i = 1; i <= bld.aboveFloors; i += 1) {
      const name = `${i}F`;
      if (!existingKeys.has(name)) missing.push({ kind: 'above', level: i, name });
    }
    for (let b = 1; b <= bld.belowFloors; b += 1) {
      const name = `B${b}`;
      if (!existingKeys.has(name)) missing.push({ kind: 'below', level: -b, name });
    }
    if (bld.hasRoof && !existingKeys.has('RF')) {
      missing.push({ kind: 'roof', level: 99, name: 'RF' });
    }
    return missing;
  }

  async function fillMissingFloorsForBuilding(bldId: string): Promise<number> {
    const bld = tree.buildings.find((b) => b.id === bldId);
    if (!bld) return 0;
    const specs = missingFloorSpecs(bld);
    for (const s of specs) {
      await adapter.upsertFloor?.({ buildingId: bld.id, kind: s.kind, level: s.level, name: s.name });
    }
    return specs.length;
  }

