                                                                  (tpl) =>
                                                                    `<button type="button" class="pacom-btn pacom-btn--sm" data-apply-zone-tpl="${escapeHtml(tpl.key)}" data-tpl-floor="${escapeHtml(f.id)}" ${!canEdit ? 'disabled' : ''}>+ ${escapeHtml(tpl.label)}</button>`
